local ccb = require("ccb")

ccb.content.define_dialogue_topic {
    id = "TALK_EXODII_MERCHANT_netherum_labyrinth_intro",
    line = { joined = {
        ccb.content.text("Ahh, now that be a weighty ask.  Not a thing ol' Rubik shares wi' every soul as wanders in, mind.  But aye, I know it, clear as day - that ye've the interface set in ye proper.  Ye carry the work in ye own flesh, so mayhaps ye've the right o' it, fair an square."),
        ccb.content.text("\"\n\n[TRANSLATE:] \""),
        ccb.content.text("Ahh, now that's a big question.  Not something I'd share with anyone who wandered in.  But yes, I know, you have one of our interfaces.  You carry our trust with you, and maybe you have the right to know."),
    } },
}

ccb.content.define_dialogue_topic {
    id = "TALK_EXODII_MERCHANT_netherum_labyrinth_intro2",
    line = { joined = {
        ccb.content.text("Hear it true:  not all we gather is from these otherlands, and otherlands like it.  At times, we happen by places this'n might call \"labyrinths.\"   Apples an' pears down to otherlands, in their own right.  The Exodii keeps the reckonin'.  An there's one \"nearby\", so t'speak, spotted by Benzete 'emself.  These places have no safe ground, an nothin' there be friendly.  Yet the ones we find seem made fer us'n.  Right convenient, if ye don't press it o'er hard.  Truth be, it's where most'o'our bright an' steelies comes from."),
        ccb.content.text("\"\n\n[TRANSLATE:] \""),
        ccb.content.text("Listen carefully:  not everything we gather comes from places like this.  Sometimes, we find places we call \"labyrinths.\"  Stairs down to other worlds.  We keep track of them.  And, one is nearby, spotted by Benzete themselves.  These places aren't safe, and they aren't friendly.  But, they seem made for us, which is convenient, if you don't think too hard about it.  Honestly, it's where most of our bionics come from."),
    } },
}

ccb.content.define_dialogue_topic {
    id = "TALK_EXODII_MERCHANT_netherum_labyrinth_intro_what",
    line = { joined = {
        ccb.content.text("What are they, ye ask?  If ol' Rubil could name it clean, mayhaps I even wouldn'.  They ain't like other otherlands.  Not places what simply are.  Willed, these.  Set.  As if some vast mind laid'em out, piece by piece.  A labor-hall built for a purpose this'n don't ken.\"\n\nRubik pauses and scratches at their chin.\n\n\"But also… well, not like any o' that, neither.  Truth be, not rightly sure they're there before we pass by, or through 'em, any road.  By and by, what us'n says o' such places is waxin' religious, more than tellin'.  Mayhap they can't be known proper."),
        ccb.content.text("\"\n\n[TRANSLATE:] \""),
        ccb.content.text("What are they, you ask?  If I knew, I'd be afraid to say.  They aren't like other places.  They don't just exist.  Something put them there, piece by piece.  A workshop of unknown purpose.  But also, not like any of that.  Honestly, not really sure if they exist before we pass by, or through them, anyway.  Anything we say about them is basically waxing religiously - maybe they can't be explained."),
    } },
}

ccb.content.define_dialogue_topic {
    id = "TALK_EXODII_MERCHANT_netherum_labyrinth_intro_what2",
    line = { joined = {
        ccb.content.text("Ye find all manner of things - treasures in troves.  But, ye trapse in, an' things where they oughtn't.  Tools laid ready.  Bright an' steelies waitin' like a snare, too fair.  Mark ol' Rubik well:  what ye find there ain't gifts.  Yer a tea leaf in the night, nickin' what you want and can.  Yer a fish, and the treasure's a hook."),
        ccb.content.text("\"\n\n[TRANSLATE:] \""),
        ccb.content.text("You find all manner of things.  But, you walk in and there are things where you might not expect them to be.  Tools ready to use.  Bionics ready to take, like bait on a snare, too tempting.  Listen carefully: you won't find gifts there.  You are a thief in the night, stealing what you want.  You're a fish, and the treasures are hooks."),
    } },
}

ccb.content.define_dialogue_topic {
    id = "TALK_EXODII_MERCHANT_netherum_labyrinth_intro_what3",
    line = { joined = {
        ccb.content.text("No, not The Enemy, but might be their trouble n' strife.  If ye' go, just wait n' see.  It'll ask.  It knows what shape to wear, or it just takes it, anyhow.  For me, an ol' friend, in the Temple of ale this'n scarce remembers.  For others, other things.  But, if it starts answerin' ye in a way just for you?  If it offers ye' a safety you think this broken world don't have?  Best be on yer way, quick and quiet.  It's a lie.  Just death by another name."),
        ccb.content.text("\"\n\n[TRANSLATE:] \""),
        ccb.content.text("No, not The Enemy, but something like their wife (Rubik is trying to be funny).  If you go, you'll see.  It'll talk to you.  It knows what shape to take, or it just takes it, anyway.  For me, an old friend, in a Temple of ale I barely remember.  For others, other things.  But, if it starts talking to you in a familiar way?  It it offers you safety?  Leave, quick and quiet.  It's a lie.  Death by another name."),
    } },
}

ccb.content.define_dialogue_topic {
    id = "TALK_EXODII_MERCHANT_netherum_labyrinth_intro_trouble_strife",
    line = { joined = {
        ccb.content.text("Heh, just ol' Rubik tryin t'be clever, where clever can't be called for.  A poor jest, at that.  Nothin' funny in it.\"\n\nRubik's tone becomes a bit more somber - more serious.  \"I meant only this:  it's not The Enemy what walks among the dead, but mayhaps say she's cut from the same cloth.  Not kin, not part of it, but this'n reckons alike, yet in its own fashion.  So don't take the jest for more than it be.  Ain't really a wife, friend, of anything of the sort, 'cause there ain't any such thing.  Mayhaps all an illusion - a jape of the lump.  But that's just my thinkin'.  Mayhaps."),
        ccb.content.text("\"\n\n[TRANSLATE:] \""),
        ccb.content.text("Heh, just trying to be funny, when I shouldn't be.  A bad joke.  Nothing funny about it.  I meant only this: it isn't the Enemy the one that raises the dead here.  But, they're maybe similar in some way.  Not family, not part of the Enemy, but maybe an equal to it.  So don't take the joke for more than a joke.  It's not its partner, its wife, or its friend, because I doubt these things have such things.  Maybe just an illusion - a trick in the head.  But that's just my thinking - it's all unknown."),
    } },
}

ccb.content.define_dialogue_topic {
    id = "TALK_EXODII_MERCHANT_netherum_labyrinth_intro_how",
    line = { joined = {
        ccb.content.text("Gettin' there a mite tricky, but not so tangled as jumpin' this whole castle.  They're less dear to go to an' fro, so t'speak, which is odd itself, I s'pose.\n\nDown below, ye'll find a ring o' metal, wi' a terminal us'n has just set up.  Ol' Rubik set the words by hand, in preparation, so ye should ken it well enough.  Ye'll be a free - a volunteer to escolt it.  Good for you, good for we - more metal for you, and sell extras to we, aye?  Ye're free to go an' make use of it.  Keep mind 'at once you jump, the ring'll need a full five day rest afore it'll take ye again.\n\nFirst time'll leave ya' addled, though, spin o' the boat race.  If ye've the grit, passes quick enough."),
        ccb.content.text("\"\n\n[TRANSLATE:] \""),
        ccb.content.text("Getting there is tricky, but easier than moving a castle.  They're less expensive and dangerous than a whole jump, which itself is curious.  Downstairs is a metal ring with a terminal - I wrote the messages, so you'll understand it.  We'll consider you a volunteer who wants to scout the place out.  It's good for both of us.  You're free to use it.  Keep in mind that the teleporter needs to recharge for 5 days between jumps.  Your first time will leave you dizzy, but it'll pass if you're tough."),
    } },
}

ccb.content.define_dialogue_topic {
    id = "TALK_EXODII_MERCHANT_netherum_labyrinth_intro_how2",
    line = { joined = {
        ccb.content.text("Last word o' threat:  Can't know what ye'll find there.  They're ever a bit different for each'n'all.  Trust not.  Tarry not.  Use yer lump and think as'n Exodii:  take what ye can, but be not tempted by treasure."),
        ccb.content.text("\"\n\n[TRANSLATE:] \""),
        ccb.content.text("A word of caution: I can't tell you what you'll find.  They're always different.  Don't trust them.  Don't linger.  Use your head, think like an Exodii:  take what you can, but don't get tempted by treasure."),
    } },
}

ccb.content.define_dialogue_topic {
    id = "TALK_EXODII_MERCHANT_netherum_labyrinth_intro_how3",
    line = { joined = {
        ccb.content.text("Fer me?  Well, twisting halls of steel, like this place, or that.  But there's another place.  A mite like a rub-a-dub house ol' Rubik scarce remembers, if it ever were.  Warm.  Wood.  Fire.  The ol' Temple for the soul, if there's any yet left.  Yet I tarry not there, trust it not a hair.  In fact, these days, I jus' don't go.  Got other things to do, like run this skip n' hop."),
        ccb.content.text("\"\n\n[TRANSLATE:] \""),
        ccb.content.text("For me?  Well, twisted halls of steel.  But there's another place.  It's a little like a pub I barely remember, if it ever existed.  Warm.  Wood.  Fire.  Like a Temple (this should be capitalized, as it's what it calls itself for Rubik) for the soul, if I still have one.  But I don't stay there or trust it.  These days, I don't even visit.  I have other things to do, like run this shop."),
    } },
}

ccb.content.define_dialogue_topic {
    id = "TALK_EXODII_MERCHANT_netherum_labyrinth_intro_NL_interface",
    line = { joined = {
        ccb.content.text("Gettin' there a mite tricky, but not so tangled as jumpin' this whole castle.  They're less dear to go to an' fro, so t'speak, which is odd itself, I s'pose.\n\nDown below, ye'll find a ring o' metal, wi' a terminal us'n has just set up.  Ol' Rubik set the words by hand, in preparation, so ye should ken it well enough.  Ye'll be a free - a volunteer to escolt it.  Good for you, good for we - more metal for you, and sell extras to we, aye?  Ye're free to go an' make use of it.  Keep mind 'at once you jump, the ring'll need a full five day rest afore it'll take ye again.\n\nI'd give ye a word o' threat, but I think ye'ken it already."),
        ccb.content.text("\"\n\n[TRANSLATE:] \""),
        ccb.content.text("Getting there is tricky, but easier than moving a castle.  They're less expensive and dangerous than a whole jump, which itself is curious.  Downstairs is a metal ring with a terminal - I wrote the messages, so you'll understand it.  We'll consider you a volunteer who wants to scout the place out.  It's good for both of us.  You're free to use it.  Keep in mind that the teleporter needs to recharge for 5 days between jumps.  I'd give you a word of caution, but you probably know the place well enough."),
    } },
}

ccb.content.define_dialogue_topic {
    id = "TALK_EXODII_MERCHANT_netherum_labyrinth_exodii_wrist_computer",
    line = { joined = {
        ccb.content.text("Ah, well now, at'll happen.  The apples n' pears - the ol' wobbly stairs to labyrinths - that is to say, how you got in, aren't stable.  Like this'n yarked, we only spotted the one on our way in.  She's likely moved.  But, I'm chuffed as a squeek to see you back after divin' in.  Maybe ye've some promise, yet.  Sure ye'll be keen to go back to the Labyrinths?  S'not a good idea."),
        ccb.content.text("\"\n\n[TRANSLATE:] \""),
        ccb.content.text("Well, that'll happen.  The entrances to those places aren't particularly stable.  Like I said, we only spotted it and recorded its location on its way in.  It's likely to have moved.  But, I'll say, I'm surprised to see you back after you went in.  Maybe you've got some promise in you, yet.  You sure you want to go back?"),
    } },
}

ccb.content.define_dialogue_topic {
    id = "TALK_EXODII_MERCHANT_netherum_labyrinth_exodii_wrist_computer_2",
    line = { joined = {
        ccb.content.text("&Rubik considers you a very moment, their metal finger tapping the counter.  Then, Rubik produces a dusty electronic device.  In juxtaposition to the stare just moments ago, Rubik unceremoniously gives you the device.  \"This'n was ol' Rubiks, some time gone by.  Also found the Labyrinths curious, and spent a lick and a split delving.  In fact, we got Exodii'll do it, now and then, when we need it.  But ken, not places like this'n - green and brown, rich in plastic n' trinkets.  But others.  Darker places.  Anyhow, this'n hasn't used that there in  a spell.  S'yours, now.\""),
        ccb.content.text("\"\n\n[TRANSLATE:] \""),
        ccb.content.text("&Rubik considers you a very moment, their metal finger tapping the counter.  Then, Rubik produces a dusty electronic device.  In juxtaposition to the stare just moments ago, Rubik unceremoniously gives you the device.  \"This was mine, some time ago.  I also found that place pretty curious, and spent too much time delving into it.  We have Exodii who do it, now and again, when we need the supplies.  Not in places like this, so rich in plastics and metals, but in others, like the one we just came from.  Anyhow, I've not used this in a long time.  It's yours now.\""),
    } },
}

ccb.content.define_dialogue_topic {
    id = "TALK_EXODII_MERCHANT_netherum_labyrinth_exodii_wrist_computer_3",
    line = { joined = {
        ccb.content.text("&Rubik leans in and starts to tap the device's screen, showing you how it works.  \"Right, guess it's all scribbles to ya'.  It's a click-clack paddywack.  A tippidy-type.  A computer.  Has a few jobs, but only a pair for you.  First, is a talk-box - a radio.  Should work, still.  Second is fer wobbles - that is, it can wibble out Labyrinths, and where they're at.  It won't finger'em to you properly, but keep it turnt on, and it'll record'em'if'it'finds'em, aye?  Then, bring'er back to the terminal downstairs.  Might use'em to delve back into a Labyrinth, for better'er'worse.\""),
        ccb.content.text("\"\n\n[TRANSLATE:] \""),
        ccb.content.text("&Rubik leans in and starts to tap the device's screen, showing you how it works.  \"Right, I guess you can't read it.  It's a computer.  Has a few uses, but only two of use to you.  First is a radio - should work just find here.  Second is to detect wobbles - that is, entrances to labyrinths.  It won't point them out properly to you, but keep it toggled on, and it'll record passively, as you go.  Then bring the data back to the terminal here, and you might use to to delve back into a Labyrinth, for better or worse.\""),
    } },
}

ccb.content.define_dialogue_topic {
    id = "TALK_EXODII_MERCHANT_netherum_labyrinth_exodii_wrist_computer_4",
    line = { joined = {
        ccb.content.text("Anyplace the fabric'a space, time, reality, n' all the bits between grows thin.  When the sky cracks, or the earth glows.  Ye'll ken it.  No doubt."),
        ccb.content.text("\"\n\n[TRANSLATE:] \""),
        ccb.content.text("Anywhere the fabric of  space, time, and reality are thin.  When the sky cracks, or the earth glows.  You'll know it when you see it."),
    } },
}
